/**
 * The app's API client for EXPO_PUBLIC_API_URL. All HTTP rules (config,
 * timeout, token origins, ApiError, 401 handling) live in httpClient.ts.
 * Feature modules build their endpoints on it in features/<name>/api/.
 */
import { getConfig } from '@/shared/config/env';
import { createHttpClient } from './httpClient';

export { getOrigin, getTrustedTokenOrigins } from './httpClient';

export const api = createHttpClient({
  getBaseURL: () => getConfig().apiUrl,
  authenticated: true,
});

export default api;
/**
 * Loads data for a screen: runs an async function on mount and whenever
 * `deps` change, and tracks loading, data, and a typed error.
 *
 * - `fetchFn` gets an AbortSignal; pass it to the request
 *   (`api.get(url, { signal })`). The previous request is aborted when deps
 *   change, on refetch, and on unmount.
 * - Only the latest request updates state, so a slow, outdated response can't
 *   overwrite a newer one (even if the server ignores the abort).
 * - `error` is an ApiError (`code`, `status`, `message`), or null.
 *
 * For caching, background refetching, and mutations, use a data library
 * instead; see docs/api-and-storage.md#loading-data-in-screens.
 */
import {
  useCallback,
  useEffect,
  useRef,
  useState,
  type DependencyList,
} from 'react';
import { toApiError, type ApiError } from '@/shared/http/apiError';

export interface UseFetchResult<T> {
  data: T | null;
  loading: boolean;
  error: ApiError | null;
  /** Runs the request again (aborting one in flight). */
  refetch: () => Promise<void>;
}

function sameDeps(a: DependencyList, b: DependencyList): boolean {
  return a.length === b.length && a.every((value, i) => Object.is(value, b[i]));
}

/**
 * @example
 * const { data, loading, error, refetch } = useFetch(
 *   signal => postsApi.list({ signal }),
 *   [userId]
 * );
 */
export function useFetch<T>(
  fetchFn: (signal: AbortSignal) => Promise<T>,
  deps: DependencyList = []
): UseFetchResult<T> {
  const [data, setData] = useState<T | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<ApiError | null>(null);

  // Re-run when deps change, compared item by item like a hook's deps. The
  // previous deps are kept in state (React's "information from previous
  // renders" pattern) so callers can pass their own dependency list.
  const [trackedDeps, setTrackedDeps] = useState(deps);
  const [depsVersion, setDepsVersion] = useState(0);
  if (!sameDeps(trackedDeps, deps)) {
    setTrackedDeps(deps);
    setDepsVersion(version => version + 1);
  }

  // The latest fetchFn, without making it a dependency (callers usually pass
  // an inline function).
  const fetchFnRef = useRef(fetchFn);
  useEffect(() => {
    fetchFnRef.current = fetchFn;
  });

  const controllerRef = useRef<AbortController | null>(null);

  const run = useCallback(async () => {
    controllerRef.current?.abort();
    const controller = new AbortController();
    controllerRef.current = controller;
    const isCurrent = () =>
      controllerRef.current === controller && !controller.signal.aborted;

    setLoading(true);
    setError(null);
    try {
      const result = await fetchFnRef.current(controller.signal);
      if (isCurrent()) setData(result);
    } catch (caught) {
      if (isCurrent()) {
        setError(toApiError(caught));
        setData(null);
      }
    } finally {
      if (isCurrent()) setLoading(false);
    }
  }, []);

  useEffect(() => {
    void run();
    return () => {
      // Unmount or deps change: drop the request and its result.
      controllerRef.current?.abort();
    };
  }, [run, depsVersion]);

  return { data, loading, error, refetch: run };
}
/**
 * Backend-agnostic authentication.
 *
 * The auth service stores the token (token store) and the user profile
 * (AsyncStorage) and drives the session; how credentials become a token and
 * what the user payload looks like is up to an AuthAdapter. To use your
 * backend, write an adapter (see docs/connect-your-backend.md)
 * and register it with setAuthAdapter() in shared/integrations/setup.ts.
 * Until one is registered, sign-in fails with a "not configured" error.
 */
import type { AxiosInstance } from 'axios';
import { getConfig } from '@/shared/config/env';
import { toApiError } from '@/shared/http/apiError';
import { createHttpClient } from '@/shared/http/httpClient';
import { logger } from '@/shared/lib/logger';
import { getItem, setItem, STORAGE_KEYS } from '@/shared/storage/storage';
import { clearStoredSession, setRefreshTokenHandler } from './session';
import { getTokenStore } from './tokenStore';

export interface LoginCredentials {
  username: string;
  password: string;
}

/** The signed-in user as the app sees it, whatever the backend returns. */
export interface AuthUser {
  id: number | string;
  email: string;
  name: string;
}

export interface AuthResponse {
  token: string;
  user: AuthUser;
}

/** HTTP clients for the auth backend (EXPO_PUBLIC_AUTH_API_URL). */
export interface AuthClients {
  /** No token; a 401 here is a wrong password, not an expired session. */
  public: AxiosInstance;
  /** Sends the stored token; a 401 here signs the user out. */
  authenticated: AxiosInstance;
}

export interface AuthAdapter {
  /** Exchanges credentials for an access token and the backend's user payload. */
  login(
    credentials: LoginCredentials,
    clients: AuthClients
  ): Promise<{ token: string; user: unknown }>;
  /** Maps the backend's user payload to AuthUser; throws if it is incomplete. */
  normalizeUser(raw: unknown): AuthUser;
  /** Loads the current user with the stored token (used by the profile screen). */
  fetchUser?(clients: AuthClients): Promise<unknown>;
  /**
   * Obtains a new access token, e.g. with a refresh token the adapter keeps;
   * null when the session can't be refreshed. Called once on a 401.
   */
  refresh?(clients: AuthClients): Promise<string | null>;
  /**
   * Ends the session on the backend and drops what the adapter keeps, e.g.
   * revokes and deletes a refresh token. Called on sign-out while the access
   * token is still stored; if it fails, the failure is logged and the user is
   * signed out anyway.
   */
  logout?(clients: AuthClients): Promise<void>;
