/**
 * Local API for the Maestro flows (scripts/e2e/run.sh starts it). Serves
 * GET /todos, and lets a flow switch the response mode:
 *
 *   POST /__mode/ok      GET /todos returns 12 todos
 *   POST /__mode/error   GET /todos returns 503 {"message": "Service unavailable"}
 *
 * Usage: node scripts/e2e/mock-api.js [port]   (default 9999)
 */
const http = require('http');

const port = Number(process.argv[2] ?? 9999);
let mode = 'ok';

const todos = Array.from({ length: 12 }, (_, index) => ({
  userId: 1,
  id: index + 1,
  title: `e2e todo ${index + 1}`,
  completed: index === 0,
}));

function send(res, status, body) {
  res.writeHead(status, { 'Content-Type': 'application/json' });
  res.end(JSON.stringify(body));
}

http
  .createServer((req, res) => {
    const modeMatch = /^\/__mode\/(ok|error)$/.exec(req.url ?? '');
    if (req.method === 'POST' && modeMatch) {
      mode = modeMatch[1];
      process.stdout.write(`mode=${mode}\n`);
      return send(res, 200, { mode });
    }
    if (req.method === 'GET' && req.url?.startsWith('/todos')) {
      process.stdout.write(`GET ${req.url} mode=${mode}\n`);
      return mode === 'error'
        ? send(res, 503, { message: 'Service unavailable' })
        : send(res, 200, todos);
    }
    send(res, 404, { message: 'Not found' });
  })
  .listen(port, () => process.stdout.write(`mock API on :${port}\n`));
import { ScrollView, StyleSheet, View } from 'react-native';
import { SafeAreaView } from 'react-native-safe-area-context';
import { Button, Card, Text, useTheme } from 'react-native-paper';
import { router } from 'expo-router';
import { useSession } from '@/shared/session/SessionProvider';
import { t } from '@/shared/i18n';

/** Home: the session card and links to the examples. */
export function HomeScreen() {
  const theme = useTheme();
  const { session, signOut } = useSession();

  return (
    <SafeAreaView
      style={[styles.container, { backgroundColor: theme.colors.background }]}
    >
      <ScrollView contentContainerStyle={styles.content}>
        <Text variant="headlineMedium" style={styles.title}>
          {t('home.title')}
        </Text>

        <Card mode="outlined" style={styles.card}>
          <Card.Content>
            <Text variant="titleMedium">{t('home.session.title')}</Text>
            <Text
              variant="bodyMedium"
              style={[styles.status, { color: theme.colors.onSurfaceVariant }]}
              testID="session-status"
            >
              {session.status === 'loading'
                ? t('home.session.checking')
                : session.status === 'signedIn'
                  ? t('home.session.signedIn', {
                      name:
                        session.user?.name ??
                        t('home.session.signedInFallbackName'),
                    })
                  : t('home.session.signedOut')}
            </Text>
          </Card.Content>
          <Card.Actions>
            {session.status === 'signedIn' ? (
              <View style={styles.actions}>
                <Button
                  mode="outlined"
                  onPress={signOut}
                  testID="logout-button"
                >
                  {t('home.session.logOut')}
                </Button>
                <Button
                  mode="contained-tonal"
                  onPress={() => router.push('/profile')}
                  testID="profile-button"
                >
                  {t('home.session.viewProfile')}
                </Button>
              </View>
            ) : (
              <Button
                mode="contained"
                onPress={() => router.push('/login')}
                disabled={session.status === 'loading'}
                testID="sign-in-button"
              >
                {t('home.session.signIn')}
              </Button>
            )}
          </Card.Actions>
        </Card>
      </ScrollView>
    </SafeAreaView>
  );
}

const styles = StyleSheet.create({
  container: {
    flex: 1,
  },
  content: {
    padding: 16,
  },
  title: {
    marginBottom: 16,
    fontWeight: 'bold',
  },
  card: {
    marginBottom: 16,
  },
  status: {
    marginTop: 4,
  },
  actions: {
    flexDirection: 'row',
    gap: 8,
  },
});

