// Starts the mock backend on a spare port, exercises every endpoint, stops it.
const { spawn } = require('child_process');
const fs = require('fs');
const path = require('path');

const root = process.argv[2];
const server = path.join(root, 'scripts/mock-backend/server.js');
const failFile = path.join(root, 'scripts/mock-backend/.fail');
const port = 4123;
const B = `http://localhost:${port}/api/v1`;

const child = spawn('node', [server], { env: { ...process.env, PORT: String(port) } });
child.stdout.on('data', d => process.stdout.write(`  server: ${d}`));

async function call(label, method, url, { body, token } = {}) {
  const res = await fetch(B + url, {
    method,
    headers: {
      ...(body ? { 'content-type': 'application/json' } : {}),
      ...(token ? { authorization: `Bearer ${token}` } : {}),
    },
    body: body ? JSON.stringify(body) : undefined,
  });
  const text = await res.text();
  console.log(`${label}: ${res.status} ${text}`);
  return text ? JSON.parse(text) : null;
}

(async () => {
  await new Promise(r => setTimeout(r, 500));
  try {
    await call('bad login', 'POST', '/sessions', { body: { email: 'field@example.com', password: 'x' } });
    const s = await call('login', 'POST', '/sessions', { body: { email: 'field@example.com', password: 'notes-123' } });
    const { access_token: at, refresh_token: rt } = s.data;
    await call('me', 'GET', '/me', { token: at });
    await call('me no token', 'GET', '/me');
    await call('notes', 'GET', '/notes', { token: at });
    await call('notes no token', 'GET', '/notes');
    fs.writeFileSync(failFile, '');
    await call('notes .fail', 'GET', '/notes', { token: at });
    fs.rmSync(failFile);
    await call('refresh', 'POST', '/sessions/refresh', { body: { refresh_token: rt } });
    await call('refresh reused', 'POST', '/sessions/refresh', { body: { refresh_token: rt } });
    await call('logout', 'DELETE', '/sessions', { token: at });
  } finally {
    child.kill();
  }
})();

